 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    boxes = {}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        boxes[color] = (r0, r1, c0, c1)

    # The one patterned rectangle provides a stencil for all hollow
    # rectangles with the same interior dimensions.
    donors = []
    for color, (r0, r1, c0, c1) in boxes.items():
        interior = [(r, c) for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
        if any(grid[r][c] == color for r, c in interior):
            donors.append((color, r0, r1, c0, c1))
    if not donors:
        return [row[:] for row in grid]
    source_color, sr0, sr1, sc0, sc1 = donors[0]
    sh, sw = sr1 - sr0 - 1, sc1 - sc0 - 1
    pattern = [[grid[r][c] == source_color for c in range(sc0 + 1, sc1)]
               for r in range(sr0 + 1, sr1)]
    out = [row[:] for row in grid]
    for color, (r0, r1, c0, c1) in boxes.items():
        if color == source_color or (r1 - r0 - 1, c1 - c0 - 1) != (sh, sw):
            continue
        for i in range(sh):
            for j in range(sw):
                out[r0 + 1 + i][c0 + 1 + j] = color if pattern[i][j] else 0
    return out
